files.test_shapes.py:
import unittest

from shapes import area, perimeter, units, format


class ShapesTest(unittest.TestCase):
    def test_perimeter(self):
        self.assertEqual(perimeter.rect(2, 3), 10)

    def test_units(self):
        self.assertEqual(units.to_mm(2), 20)

    def test_format(self):
        self.assertEqual(format.fmt(2), "2.00")

    def test_area(self):
        self.assertEqual(area.rect(2, 3), 6)


if __name__ == "__main__":
    unittest.main()

